cat > /app/output/brush_render.cpp <<'CPP'
#include <cmath>
#include <algorithm>
extern "C" {
void render(const double* p, int n, double* out, int size, double mmpp) {
 std::fill(out,out+size*size,0.0);
 for(int i=0;i<n;i++) {
  double x=p[4*i], y=p[4*i+1], w=p[4*i+2], th=p[4*i+3];
  if(w<0.001) continue;
  double z=(w+0.3)/1.187, d=1.38+1.075*z;
  double ex=cos(th),ey=sin(th),nx=-ey,ny=ex;
  int x0=std::max(0,(int)floor((x-d*std::max(ex,0.)-w/2*abs(nx))/mmpp)-2);
  int x1=std::min(size-1,(int)ceil((x-d*std::min(ex,0.)+w/2*abs(nx))/mmpp)+2);
  int y0=std::max(0,(int)floor((y-d*std::max(ey,0.)-w/2*abs(ny))/mmpp)-2);
  int y1=std::min(size-1,(int)ceil((y-d*std::min(ey,0.)+w/2*abs(ny))/mmpp)+2);
  for(int j=y0;j<=y1;j++) for(int k=x0;k<=x1;k++) {
   double qx=(k+.5)*mmpp-x,qy=(j+.5)*mmpp-y;
   double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
   double f=d*(1-4*t*t/(w*w))-s;
   double g=sqrt(1+pow(8*d*t/(w*w),2));
   double a=std::max(0.,std::min(1.,std::min(s,f/g)/mmpp+.5));
   out[j*size+k]=std::max(out[j*size+k],a);
  }
 }
}
}
CPP
g++ -O3 -shared -fPIC /app/output/brush_render.cpp -o /app/output/brush_render.so

